Set-Location c:\TAIF\scs-platform
Write-Output "=== P13 safety posture (runbook section 2 checklist, executed) ==="
docker exec scs-postgres psql -U scs -d scs_platform -tAc "select key, enabled, updated_by from feature_flags where key='p13.pilot.enabled'"
Write-Output "FEATURE_FLAGS_EXIT=$LASTEXITCODE (no output above = absent row = pilot off)"
docker exec scs-postgres psql -U scs -d scs_platform -tAc "select count(*) from p13_pilot_allowlist"
Write-Output "ALLOWLIST_COUNT_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -tAc "select control_key, paused, reason, updated_by, updated_at from ops_controls order by updated_at desc"
Write-Output "OPS_CONTROLS_EXIT=$LASTEXITCODE (no output above = no control row = not paused)"
docker exec scs-postgres psql -U scs -d scs_platform -tAc "select count(*) from ops_alerts where status in ('PENDING','SENT')"
Write-Output "OPEN_ALERTS_EXIT=$LASTEXITCODE"
Write-Output "=== evidence collection SQL (runbook section 9.1), all statements ==="
docker exec scs-postgres psql -U scs -d scs_platform -c "select lease_key, holder_id, epoch, poll_failures, last_error_code from worker_leases;"
Write-Output "SQL_LEASE_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -c "select id, dedup_key, severity, status, title, detail, fire_count, suppressed_count, attempt_count, delivery_channel, last_error, org_id, resource_type, resource_id, first_observed_at, last_observed_at, delivered_at, resolved_at from ops_alerts where condition_key = 'p13.worker.poll_failures' order by last_observed_at desc limit 50;"
Write-Output "SQL_ALERTS_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -c "select * from ops_controls;"
Write-Output "SQL_CONTROLS_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -c "select control_key, paused, reason, actor_id, actor_kind, changed_at from ops_control_audit order by changed_at desc;"
Write-Output "SQL_AUDIT_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -c "select key, enabled, updated_by from feature_flags where key = 'p13.pilot.enabled';"
Write-Output "SQL_FLAG_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -c "select org_id, store_id, enabled, note, created_by, updated_at from p13_pilot_allowlist order by org_id, store_id;"
Write-Output "SQL_ALLOW_EXIT=$LASTEXITCODE"
docker exec scs-postgres psql -U scs -d scs_platform -c "select id, org_id, sub_order_id, return_request_id, adjustment_type, status, fx_status, fx_rate_source, fx_rate, requires_dual_approval, approval_hash, amount_minor, usd_equivalent_minor, currency, created_by, created_at, updated_at from settlement_adjustments order by created_at desc limit 50;"
Write-Output "SQL_ADJ_EXIT=$LASTEXITCODE"
